    'Jaunesniems nei 14 metų reikia tėvų el. pašto - tėvai turės patvirtinti registraciją.' => 'Under 14 years parents\' e-mail is needed - parents will have to confirm the registration.',
    'Jaunimas' => 'Teens',
    'Jaunimui' => 'For teens',
    'Jei paskyra laukia patvirtinimo, naują nuorodą išsiuntėme el. paštu.' => 'If the account is awaiting approval, we have sent a new link by e-mail.',
    'Jei toks el. paštas registruotas, išsiuntėme nuorodą slaptažodžiui atkurti.' => 'If this e-mail is registered, we have sent a password reset link.',
    'Jei tėvai dar neturi paskyros - palikite tuščią. Kai užsiregistruos, susiekite nario puslapyje, kad tas pats vaikas nebūtų sukurtas du kartus.' => 'If the parents do not have an account yet - leave empty. When they register, link them on the member page so that the same child is not created twice.',
    'Jei vaikas turi savo el. paštą, jis gali turėti' => 'If the child has their own e-mail, they can have',
    'Jei įrašyta - rodoma viršutiniame meniu' => 'If filled in - shown in the top menu',
    'Junior gauna pastabą ir užduotį su pamoka - „Svarbu“, „Atlikta“.' => 'Junior gets a note and a task with a lesson - "Important", "Done".',
    'Junior pažymi kito diržo programos punktus „Moku“ - Denis tvirtina, skiriami XP (jei programa surašyta).' => 'Junior marks next-belt programme items "I can do it" - Denis approves, XP awarded (if the programme exists).',
    'Juodraštis išsaugotas.' => 'Draft saved.',
    'Juodraščiai ir suplanuotos - mato tik treneriai' => 'Drafts and scheduled - only coaches see them',
    'Juosta su tekstu' => 'Banner with text',
    'Ją tėvai (ar suaugęs narys) pasirašo elektroniniu parašu per Edufi. Sutartyje yra nario vardas, pavardė ir gimimo data, tėvų (globėjų) vardas, pavardė, telefonas ir el. paštas.
     Šiuo el. paštu siunčiame informaciją apie treniruotes, renginius ir tvarkaraščio pakeitimus.
     Klubui taip pat pateikiate gydytojo pažymą, kad narys gali sportuoti, į svetainę ji nekeliama. Pagrindas - narystės sutartis.' => 'Parents (or an adult member) sign it with an electronic signature via Edufi. The contract contains the member\'s name, surname and date of birth, the parents\' (guardians\') name, surname, phone and e-mail. We use this e-mail to send information about trainings, events and schedule changes. You also give the club a doctor\'s certificate that the member may do sports; it is not uploaded to the website. Basis - the membership contract.',
    'Jėga, forma ir aiški galva po darbo dienos' => 'Strength, fitness and a clear head after a working day',
    'Jūs' => 'You',
