    'Kiekvienas pažymėtas narys gaus pastabą su šia pamoka savo paskyroje (tėvai - vaiko paskyroje) ir galės jums atsakyti. Atsakymus matysite skiltyje „Žinutės“.' => 'Each selected member will get a note with this lesson in their account (parents - in the child\'s account) and will be able to reply to you. You will see the replies in "Messages".',
