    'Kokį bloką pridėti?' => 'Which block to add?',
    'Kol kas varžybas kurkite kaip įprastą renginį (Renginiai → „+ Naujas renginys“, tipas „Varžybos“), o rezultatus įrašykite renginio rezultatuose.' => 'For now create competitions as a regular event (Events → "+ New event", type "Competition") and enter the results in the event results.',
