    'Mus vienija ne tik technikos tobulinimas, bet ir noras augti kaip asmenybėms — stiprinti kūną, ugdyti charakterį ir mokytis pagarbos sau bei aplinkiniams.' => 'We are united not only by improving technique but also by the wish to grow as individuals - to strengthen the body, build character and learn respect for ourselves and others.',
