    'Svetainė veikia per šifruotą HTTPS ryšį. Slaptažodžiai saugomi tik užšifruoti. Narių duomenis mato tik prisijungę treneriai,
     jų paskyroms galima įjungti prisijungimą su papildomu kodu el. paštu. Kasdien daroma atsarginė duomenų bazės kopija.' => 'The website works over an encrypted HTTPS connection. Passwords are stored only encrypted. Members\' data is seen only by logged-in coaches; their accounts can use login with an additional code by e-mail. A database backup is made every day.',
    'Svetainėje (Renginiai ir Mano paskyra) - visada' => 'On the website (Events and My account) - always',
    'Svetainės versija' => 'Website version',
    'Svetainės versija (rodoma tik testuojant)' => 'Website version (shown only when testing)',
    'Svetainės šriftai įkeliami iš „Google Fonts“, o vaizdo įrašai rodomi per „YouTube“ privatumo režimu (youtube-nocookie.com).
     Įkeliant šį turinį jūsų naršyklė susisiekia su „Google“ serveriais ir perduoda jūsų IP adresą.' => 'The website fonts are loaded from "Google Fonts", and videos are shown via "YouTube" in privacy mode (youtube-nocookie.com). When loading this content your browser contacts Google\'s servers and passes on your IP address.',
    'Svetainę ir el. paštą talpina domenai.lt (Lietuva). Narystės sutartys pasirašomos per Edufi. Jie duomenų nenaudoja savo tikslais.
        SMS žinučių kol kas nesiunčiame - pasirinkus SMS teikėją, jis bus nurodytas čia.' => 'The website and e-mail are hosted by domenai.lt (Lithuania). Membership contracts are signed via Edufi. They do not use the data for their own purposes. We do not send SMS yet - once an SMS provider is chosen, it will be listed here.',
