    'Už tai, kas nesiskaičiuoja automatiškai: pagalba treneriui, treniruotės vedimas, teisėjavimas... Pažymėkite kelis vaikus ar visą grupę - taškų gaus kiekvienas, o paskyroje matys, už ką.' => 'For things not counted automatically: helping the coach, leading a training, refereeing... Select several children or a whole group - each gets the XP and sees in the account what for.',
