    'Tuščios eilutės nesiunčiamos.' => 'Empty rows are not sent.',
    'Duomenys naudojami tik šioms varžyboms organizuoti (kategorijos, lentelės, rezultatai). Viešai vaikų ir jaunių iki 18 m. rodomas vardas ir pavardės pirmoji raidė.' => 'The data is used only to organise this competition (categories, brackets, results). Publicly, children and juniors under 18 are shown with their first name and the first letter of the surname.',
