    'tėvų tel. Nr.' => 'parent\'s phone',
    'Sutinka būti fotografuojamas ir filmuojamas' => 'Agrees to be photographed and filmed',
    'nuotraukos?' => 'photos?',
    'Tuščios eilutės nesiunčiamos. Vaikams iki 18 m. - būtinas vieno iš tėvų telefonas.' => 'Empty rows are not sent. For children under 18 a parent\'s phone is required.',
    'Duomenys naudojami tik šioms varžyboms organizuoti: kategorijos, lentelės, tvarkaraštis, rezultatai. Telefonai - tik susisiekti dėl varžybų; jie ištrinami praėjus mėnesiui po varžybų. Varžybų lentelėse ir rezultatuose rodomas vardas, pavardė ir klubas; vaikų ir jaunių iki 18 m. - vardas ir pavardės pirmoji raidė.' => 'The data is used only to organise this competition: categories, brackets, schedule, results. Phone numbers are used only to contact you about the competition and are deleted one month after it. Brackets and results show the name, surname and club; for children and juniors under 18 - the first name and the initial of the surname.',
    'Duomenų valdytojas - VšĮ Karate Ateitis.' => 'Data controller - VšĮ Karate Ateitis.',
    'Turite teisę susipažinti su savo duomenimis, juos ištaisyti ar paprašyti ištrinti:' => 'You have the right to see your data, correct it or ask for it to be deleted:',
    'Varžybų metu fotografuojama ir filmuojama. Dalyvių, kurie nesutinka, nuotraukų ir video organizatorius neskelbia.' => 'Photos and video are taken during the competition. The organiser does not publish photos or video of participants who do not agree.',
    'Sutinku, kad organizatoriai naudotų pateiktus duomenis varžybų organizavimui.' => 'I agree that the organisers may use the data provided to organise the competition.',
    'privatumo politika' => 'privacy policy',
    '{name}: pasirinkite, ar sutinka būti fotografuojamas ir filmuojamas.' => '{name}: choose whether they agree to be photographed and filmed.',
    '{name}: patikrinkite telefono numerį.' => '{name}: check the phone number.',
    '{name}: įrašykite vieno iš tėvų telefono numerį.' => '{name}: enter a parent\'s phone number.',
    'Įrašykite kontaktinį telefono numerį - jei kas neaišku, susisieksime.' => 'Enter a contact phone number - we will call if anything is unclear.',
    'Pažymėkite sutikimą dėl duomenų naudojimo ir kad susipažinote su privatumo politika.' => 'Tick the consent to data use and that you have read the privacy policy.',
    'Kitų klubų dalyvius per registracijos nuorodą užregistruoja jų treneris ar tėvai: vardas, pavardė, gimimo metai, lytis, diržas, klubas, kontaktinis ir vieno iš tėvų telefonas, sutikimas dėl nuotraukų ir video. Telefonai ištrinami praėjus mėnesiui po varžybų.' => 'Participants from other clubs are registered through the registration link by their coach or parents: name, surname, year of birth, gender, belt, club, contact phone and a parent\'s phone, consent to photos and video. Phone numbers are deleted one month after the competition.',
