    // v1.28
    'Bandymo nuoroda sukurta - nukopijuokite ir nusiųskite.' => 'Test link created - copy it and send it.',
    'Bandymo nuoroda išjungta - su ja nebeprisijungs.' => 'Test link turned off - it no longer works.',
    'Bandymo varžybos sukurtos: išgalvoti dalyviai, kategorijos sudarytos, dalis kovų jau įvyko.' => 'Trial competition created: made-up participants, categories ready, some bouts already played.',
    '👋 Sveiki,' => '👋 Hello,',
    'Tai Budo varžybų sistemos bandymas: galite daryti viską, ką daro sekretoriatas ir organizatorius - kurti varžybas, dalyvius, kategorijas, vesti kovas, siųsti apdovanojimams.' => 'This is a trial of the Budo competition system: you can do everything the secretariat and organiser do - create competitions, participants and categories, run bouts, send to awards.',
    'Pradėkite nuo „🎲 Sukurti test varžybas“ - bus išgalvoti dalyviai ir dalis kovų. Pastebėjimus rašykite per' => 'Start with “🎲 Create test competition” - it adds made-up participants and some bouts. Write your remarks via',
    '(apačioje kairėje) - galima įklijuoti ekrano nuotrauką (Ctrl+V).' => '(bottom left) - you can paste a screenshot (Ctrl+V).',
    '👀 Duoti išbandyti (be paskyros)' => '👀 Let someone try it (no account)',
    '- draugui ar kito klubo sekretoriatui' => '- for a friend or another club\'s secretariat',
    'Su šia nuoroda žmogus įrašo savo vardą ir gali daryti viską, ką daro adminas, bet tik bandymo varžybose: tikrų klubo narių ir jų duomenų nemato, karateka.lt valdymo neatidaro. Atsiliepimus (💡) matysite Valdymas → Atsiliepimai.' => 'With this link a person enters their name and can do everything an admin does, but only in trial competitions: they don\'t see real club members or their data and can\'t open the karateka.lt admin. Their feedback (💡) appears in Admin → Feedback.',
