    'Peržiūros nuoroda išjungta.' => 'Review link turned off.',
    'LTKF peržiūra' => 'LTKF review',
    'LTKF svetainės peržiūra' => 'LTKF website review',
    'Nuoroda federacijos nariams: atsidarę jie mato LTKF svetainę ir gali palikti atsiliepimus (💡, galima įklijuoti nuotrauką). Nuorodos į karateka.lt nemato - ją mato tik adminas.' => 'A link for federation members: they see the LTKF website and can leave feedback (💡, screenshots can be pasted). They don\'t see the link to karateka.lt - only the admin does.',
    'Sukurti peržiūros nuorodą' => 'Create a review link',
    'Atidaryti LTKF svetainę →' => 'Open the LTKF website →',
    'Nuoroda jau panaudota arba pasibaigė. Paprašykite trenerio atsiųsti naują.' => 'The link has already been used or has expired. Ask the coach to send a new one.',
    'Šis narys jau turi savo paskyrą. Jei esate tėvai - pasirinkite „Aš - tėvai ar globėjai“.' => 'This member already has their own account. If you are a parent, choose “I am a parent or guardian”.',
    'Narys pridėtas prie jūsų paskyros:' => 'Member added to your account:',
