    'Kvietimas į karateka.lt' => 'Invitation to karateka.lt',
    'Treneris pridėjo šį narį į klubo sistemą. Susikurkite prisijungimą - matysite tvarkaraštį, renginius, aktyvumo taškus ir klubo žaidimą.' => 'The coach added this member to the club system. Create a login to see the schedule, events, XP and the club game.',
