    'El. paštas pakvietimui' => 'Email for the invitation',
    'nebūtina - tėvų ar paties nario' => 'optional - a parent\'s or the member\'s own',
    'Jei paskyra su šiuo el. paštu jau yra - susiesime iš karto. Jei nėra - išsiųsime pakvietimą susikurti prisijungimą. Be el. pašto gausite nuorodą, kurią galima nusiųsti žinute: užsiregistravęs per ją žmogus bus susietas su šiuo nariu.' => 'If an account with this email exists, we link it right away. If not, we send an invitation to create a login. Without an email you get a link to send in a message: whoever registers through it is linked to this member.',
