    'norėdami nustatyti naują slaptažodį, paspauskite nuorodą:' => 'To set a new password, click the link:',
    'Nuoroda galioja 1 valandą. Jei slaptažodžio nekeitėte, šį laišką ignoruokite.' => 'The link is valid for 1 hour. If you did not ask to change your password, ignore this e-mail.',
    'Kvietimas į karateka.lt - {child}' => 'Invitation to karateka.lt - {child}',
    'VšĮ Karate Ateitis treneris pridėjo {child} į klubo narių sistemą karateka.lt.' => 'A VšĮ Karate Ateitis coach has added {child} to the club member system karateka.lt.',
    'Susikurkite prisijungimą - matysite tvarkaraštį, renginius ir XP:' => 'Create your login - you will see the schedule, events and XP:',
    'Nuoroda galioja 60 dienų. Jei jau turite paskyrą karateka.lt - prisijunkite ir atidarykite nuorodą: narys bus pridėtas prie jūsų paskyros.' => 'The link is valid for 60 days. If you already have a karateka.lt account, log in and open the link: the member will be added to your account.',
