    'Trinama automatiškai' => 'Deleted automatically',
    'Narių, egzaminų, varžybų rezultatai ir naujienos lieka, kol juos ištrina treneris ar administratorius.' => 'Members, exam and competition results and news stay until a coach or an admin deletes them.',
