    'Visi naudojami slapukai:' => 'All cookies we use:',
    'prisijungimo sesija; ištrinamas uždarius naršyklę ar atsijungus.' => 'login session; removed when you close the browser or log out.',
    '„Pasitikėti šiuo įrenginiu“ (tik jei pažymėjote);' => '"Trust this device" (only if you ticked it);',
