    'atsiliepimų mygtukas: kad matytumėte savo atsiliepimus ir atsakymus į juos; 2 metai.' => 'feedback button: so you can see your feedback and the replies; 2 years.',
    'Be slapukų, naršyklės atmintyje (tik jūsų įrenginyje, į serverį nesiunčiama) laikomi patogumo nustatymai: Budo varžybų skirtukai, tema ir garsas, dar neišsaugoti varžybų pakeitimai (iki 2 d.), žaidimo pasirinkimai, kurie pranešimai jau parodyti.' => 'Besides cookies, the browser storage (only on your device, never sent to the server) keeps convenience settings: Budo tabs, theme and sound, unsaved competition changes (up to 2 days), game choices, which notices were already shown.',
    'Buvę nariai (neaktyvūs ilgiau nei metus)' => 'Former members (inactive for over a year)',
    'Sprendimas: buvusių narių duomenys saugomi 1 metus. Ištrinamas narys su lankomumu, XP, pastabomis ir žinutėmis; egzaminų registras (federacija) lieka.' => 'Decision: former members\' data are kept for 1 year. The member is deleted with attendance, XP, notes and messages; the exam register (federation) stays.',
    'Nepatvirtinti nariai (laukia ilgiau nei 90 dienų)' => 'Unapproved members (waiting over 90 days)',
    'Užsiregistravo, bet treneris taip ir nepatvirtino. Jei reikia - pirmiau patvirtinkite (Valdymas → Patvirtinimai).' => 'Signed up but never approved by a coach. If needed, approve first (Valdymas → Patvirtinimai).',
